import re

def parse_size(text: str) -> int:
    if not isinstance(text, str):
        raise ValueError("Input must be a string")
    s = text.strip()
    if not s:
        raise ValueError("Empty or whitespace only")

    # Match number (integer or decimal) followed by optional unit (letters)
    m = re.fullmatch(r'([0-9]+(?:\.[0-9]*)?|\.[0-9]+)\s*([a-zA-Z]*)', s)
    if not m:
        raise ValueError("Invalid format")

    num_str, unit = m.groups()
    try:
        num = float(num_str)
    except ValueError:
        raise ValueError("Invalid number")

    if num < 0:
        raise ValueError("Negative number")

    unit_lower = unit.lower()
    multipliers = {
        '': 1,
        'b': 1,
        'kb': 1000,
        'kib': 1024,
        'mb': 10**6,
        'mib': 2**20,
        'gb': 10**9,
        'gib': 2**30,
    }
    if unit_lower not in multipliers:
        raise ValueError("Unknown unit")

    result = num * multipliers[unit_lower]
    return int(round(result))
