def stable_unique(items):
    def deep_eq(a, b):
        if type(a) is not type(b):
            return False
        if isinstance(a, dict):
            if len(a) != len(b):
                return False
            for key in a:
                if key not in b:
                    return False
                if not deep_eq(a[key], b[key]):
                    return False
            return True
        if isinstance(a, (list, tuple)):
            if len(a) != len(b):
                return False
            return all(deep_eq(x, y) for x, y in zip(a, b))
        return a == b

    result = []
    for item in items:
        if not any(deep_eq(item, seen) for seen in result):
            result.append(item)
    return result
