def top_k_counts(words: list[str], k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []

    first_occurrence = {}  # lowercase -> (original, index)
    freq = {}

    for idx, word in enumerate(words):
        key = word.lower()
        if key not in first_occurrence:
            first_occurrence[key] = (word, idx)
        freq[key] = freq.get(key, 0) + 1

    items = [(key, freq[key], first_occurrence[key][0], first_occurrence[key][1]) for key in freq]
    items.sort(key=lambda x: (-x[1], x[3]))

    return [(orig, count) for _, count, orig, _ in items[:k]]
