import json
import math

def parse_jsonl_metrics(lines: list[str]) -> dict:
    result = {}
    invalid = 0
    services = {}

    for line in lines:
        if not line.strip():
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            invalid += 1
            continue

        if not isinstance(obj, dict):
            invalid += 1
            continue

        service = obj.get("service")
        latency = obj.get("latency_ms")
        status = obj.get("status")

        if not isinstance(service, str) or not isinstance(latency, (int, float)) or not isinstance(status, (int, float)):
            invalid += 1
            continue

        if service not in services:
            services[service] = {"latencies": [], "ok": 0, "count": 0}

        services[service]["latencies"].append(latency)
        services[service]["count"] += 1
        if 200 <= status < 300:
            services[service]["ok"] += 1

    for svc, data in services.items():
        n = data["count"]
        ok_rate = data["ok"] / n if n > 0 else 0.0
        if n == 0:
            p95 = None
        else:
            sorted_lat = sorted(data["latencies"])
            idx = math.ceil(0.95 * n) - 1
            p95 = sorted_lat[idx]
        result[svc] = {
            "count": n,
            "ok_rate": ok_rate,
            "p95_latency_ms": p95
        }

    result["invalid"] = invalid
    # 按服务名排序，但invalid键放在最后？题目要求返回{"invalid": N, "<service>": {...}, ...}，键按服务名排序。通常invalid放在最前，但排序时只对服务名排序，invalid固定位置。我们按题目要求：键按服务名排序，但invalid是特殊键，我们将其放在最前，然后服务名排序。或者直接构建有序字典，先放invalid，再放排序的服务。这里我们按常规做法：先放invalid，然后按服务名排序。
    ordered = {"invalid": invalid}
    for svc in sorted(result.keys() - {"invalid"}):
        ordered[svc] = result[svc]
    return ordered
