import heapq
from collections import defaultdict

class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__(f"Cycle detected: {cycle}")
        self.cycle = cycle

def dependency_plan(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    # 检查未知节点
    node_set = set(nodes)
    for a, b in edges:
        if a not in node_set or b not in node_set:
            raise ValueError("Unknown node in edges")

    # 去重边
    unique_edges = set(edges)

    # 构建邻接表和入度
    adj = defaultdict(list)
    indegree = {node: 0 for node in nodes}
    for a, b in unique_edges:
        adj[a].append(b)
        indegree[b] += 1

    # 最小堆，保证字典序最小
    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    # 如果结果长度不等于节点数，说明存在环
    if len(result) != len(nodes):
        # 找出一个实际环路
        remaining = set(nodes) - set(result)
        # 从剩余节点中任选一个开始DFS找环
        start = next(iter(remaining))
        # 状态：0未访问，1在栈中，2已访问
        state = {node: 0 for node in nodes}
        stack = []
        cycle = None

        def dfs(u):
            nonlocal cycle
            state[u] = 1
            stack.append(u)
            for v in adj[u]:
                if state[v] == 1:
                    # 找到环，从v开始截取
                    idx = stack.index(v)
                    cycle = stack[idx:] + [v]
                    return True
                elif state[v] == 0:
                    if dfs(v):
                        return True
            stack.pop()
            state[u] = 2
            return False

        # 从所有未处理节点尝试，但只需一个即可
        for node in remaining:
            if state[node] == 0:
                if dfs(node):
                    break

        if cycle is None:
            # 理论上不会发生，但保险
            cycle = [start, start]
        raise CycleError(cycle)

    return result
