class StreamingGroupSum:
    def __init__(self, rows):
        self.rows = rows
        self.invalid_count = 0

    def __iter__(self):
        totals = {}
        order = []
        for row in self.rows:
            try:
                _, key, value = row
            except (ValueError, TypeError):
                self.invalid_count += 1
                continue
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                self.invalid_count += 1
                continue
            if key not in totals:
                totals[key] = value
                order.append(key)
            else:
                totals[key] += value
        for key in order:
            yield (key, totals[key])

def streaming_group_sum(rows):
    return StreamingGroupSum(rows)
