import time

def retry_call(fn, attempts, retry_if, *, base_delay=0.01, sleep=time.sleep):
    if attempts <= 0:
        raise ValueError("attempts must be > 0")
    last_exc = None
    for attempt in range(1, attempts + 1):
        try:
            return fn()
        except Exception as exc:
            last_exc = exc
            if not retry_if(exc) or attempt == attempts:
                raise
            delay = base_delay * (2 ** (attempt - 1))
            sleep(delay)
    raise last_exc
