import copy

def apply_patch_ops(document: dict, operations) -> dict:
    result = copy.deepcopy(document)
    for op, path, value in operations:
        keys = path.split('.')
        if op == 'set':
            node = result
            for key in keys[:-1]:
                if key not in node or not isinstance(node[key], dict):
                    node[key] = {}
                node = node[key]
            node[keys[-1]] = value
        elif op == 'delete':
            node = result
            for key in keys[:-1]:
                if key not in node or not isinstance(node[key], dict):
                    break
                node = node[key]
            else:
                if keys[-1] in node:
                    del node[keys[-1]]
        elif op == 'increment':
            if not isinstance(value, (int, float)):
                raise TypeError("increment value must be int or float")
            node = result
            for key in keys[:-1]:
                if key not in node or not isinstance(node[key], dict):
                    raise KeyError(f"path '{path}' does not exist")
                node = node[key]
            if keys[-1] not in node:
                raise KeyError(f"path '{path}' does not exist")
            current = node[keys[-1]]
            if not isinstance(current, (int, float)):
                raise TypeError(f"path '{path}' is not numeric")
            node[keys[-1]] = current + value
        else:
            raise ValueError(f"unsupported op: {op}")
    return result
