import threading
from collections import deque

class BoundedQueue:
    def __init__(self, capacity):
        self._q = deque()
        self._cap = capacity
        self._closed = False
        self._cond = threading.Condition()

    def put(self, item):
        with self._cond:
            while not self._closed and len(self._q) >= self._cap:
                self._cond.wait()
            if self._closed:
                raise RuntimeError("Queue is closed")
            self._q.append(item)
            self._cond.notify_all()

    def get(self):
        with self._cond:
            while not self._closed and len(self._q) == 0:
                self._cond.wait()
            if self._closed and len(self._q) == 0:
                raise RuntimeError("Queue is closed and empty")
            item = self._q.popleft()
            self._cond.notify_all()
            return item

    def close(self):
        with self._cond:
            if not self._closed:
                self._closed = True
                self._cond.notify_all()
